package com.assetsphere.modules.asset; import java.util.UUID; import jakarta.persistence.*; import lombok.Getter; import com.assetsphere.modules.common.BaseEntity;
@Getter @Entity @Table(name="asset_versions") public class AssetVersion extends BaseEntity { @Column(name="asset_id",nullable=false) private UUID assetId; @Column(name="version_number",nullable=false) private int versionNumber; @Column(name="original_filename",nullable=false,length=512) private String originalFilename; @Column(name="mime_type",nullable=false,length=255) private String mimeType; @Column(name="file_size",nullable=false) private long fileSize; @Column(name="checksum_sha256",nullable=false,length=64) private String checksumSha256; @Column(name="storage_object_id",nullable=false) private UUID storageObjectId; @Column(name="uploaded_by_user_id",nullable=false) private UUID uploadedByUserId; @Enumerated(EnumType.STRING) @Column(name="processing_status",nullable=false,length=32) private AssetProcessingStatus processingStatus; protected AssetVersion(){} public static AssetVersion initial(Asset asset,String filename,String mimeType,long size,String checksum,UUID storageObjectId,UUID uploadedBy){AssetVersion version=new AssetVersion();version.assetId=asset.getId();version.versionNumber=1;version.originalFilename=filename;version.mimeType=mimeType;version.fileSize=size;version.checksumSha256=checksum;version.storageObjectId=storageObjectId;version.uploadedByUserId=uploadedBy;version.processingStatus=AssetProcessingStatus.UPLOADED;return version;} }
